import{P as i}from"./chunks/theme.CiV3X8Tm.js";import{o as l,c as e,aP as t,E as r}from"./chunks/framework.DBzxNud0.js";const c=JSON.parse('{"title":"阅读指南","description":"","frontmatter":{},"headers":[],"relativePath":"pages/guide.md","filePath":"pages/guide.md"}'),o={name:"pages/guide.md"},p=Object.assign(o,{setup(n){return(s,a)=>(l(),e("div",null,[a[0]||(a[0]=t('<h1 id="阅读指南" tabindex="-1">阅读指南 <a class="header-anchor" href="#阅读指南" aria-label="Permalink to &quot;阅读指南&quot;">​</a></h1><p>欢迎来到 fe-handbook。这是一套围绕 <strong>LLM 大模型、后端开发、前端工程</strong> 持续沉淀的技术手册，内容覆盖基础原理、工程实践、问题排查与项目复盘。</p><h2 id="导航目录" tabindex="-1">导航目录 <a class="header-anchor" href="#导航目录" aria-label="Permalink to &quot;导航目录&quot;">​</a></h2><ul><li><a href="#内容方向">内容方向</a></li><li><a href="#阅读建议">阅读建议</a></li><li><a href="#个人沉淀">个人沉淀</a></li></ul><h2 id="内容方向" tabindex="-1">内容方向 <a class="header-anchor" href="#内容方向" aria-label="Permalink to &quot;内容方向&quot;">​</a></h2><h3 id="llm-大模型" tabindex="-1">LLM 大模型 <a class="header-anchor" href="#llm-大模型" aria-label="Permalink to &quot;LLM 大模型&quot;">​</a></h3><p>聚焦大模型应用开发与工程落地，主要包括：</p><ul><li>Python 与 FastAPI 应用基础</li><li>Prompt Engineering 与上下文设计</li><li>RAG 检索增强生成</li><li>LangChain、LangGraph 与 Agent 开发</li><li>大模型应用的评估、部署与实践复盘</li></ul><h3 id="后端开发" tabindex="-1">后端开发 <a class="header-anchor" href="#后端开发" aria-label="Permalink to &quot;后端开发&quot;">​</a></h3><p>覆盖服务端开发、微服务架构与基础设施，主要包括：</p><ul><li>Java、Python 与 Node.js 服务端开发</li><li>Spring Boot、Spring Cloud 与微服务体系</li><li>Nacos、Gateway、Sentinel、Seata 等组件</li><li>Redis、RabbitMQ、数据库与缓存设计</li><li>Nginx、Linux、Docker、HTTP 与服务治理</li></ul><h3 id="前端工程" tabindex="-1">前端工程 <a class="header-anchor" href="#前端工程" aria-label="Permalink to &quot;前端工程&quot;">​</a></h3><p>系统整理 Web 前端基础、框架原理与工程化实践，主要包括：</p><ul><li>HTML、CSS、JavaScript 与 TypeScript</li><li>浏览器原理、网络、安全与性能优化</li><li>Vue、React 及其生态与源码实现</li><li>Webpack、Vite、Git 与前端工程化</li><li>SSR、微前端、数据结构与算法</li></ul><h2 id="阅读建议" tabindex="-1">阅读建议 <a class="header-anchor" href="#阅读建议" aria-label="Permalink to &quot;阅读建议&quot;">​</a></h2><p>你可以根据目标选择阅读路径，无需严格按照目录顺序学习：</p><ol><li><strong>LLM 应用方向</strong>：先了解 Python 与模型基础，再学习 Prompt、RAG、LangChain、LangGraph 和 Agent。</li><li><strong>后端开发方向</strong>：从一门服务端语言开始，逐步学习数据库、中间件、微服务与部署运维。</li><li><strong>前端开发方向</strong>：先掌握 HTML、CSS、JavaScript，再进入 Vue、React、浏览器原理与工程化。</li><li><strong>综合提升方向</strong>：结合数据结构、设计模式、性能优化、项目实践和工作复盘，建立完整知识体系。</li></ol><div class="tip custom-block"><p class="custom-block-title">阅读提示</p><p>每篇文档可以独立阅读。遇到不熟悉的概念时，可通过顶部导航、侧边栏或站内搜索快速定位相关专题。</p></div><h2 id="个人沉淀" tabindex="-1">个人沉淀 <a class="header-anchor" href="#个人沉淀" aria-label="Permalink to &quot;个人沉淀&quot;">​</a></h2><p>这里记录开发过程中的长期积累，不只罗列知识点，也关注知识如何应用到真实问题中：</p><ul><li>学习过程中的技术笔记</li><li>项目中的实战经验</li><li>问题排查与性能优化思路</li><li>方案设计、技术选型与工作复盘</li></ul>',21)),r(i)]))}});export{c as __pageData,p as default};
